<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Bouncing Ball Playground</title>
<style>
  :root { color-scheme: dark; }
  html, body { height: 100%; margin: 0; }
  body {
    background: radial-gradient(1200px 800px at 50% -10%, #1a2236, #0a0d14 70%);
    color: #e8eef7;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 24px 20px;
    box-sizing: border-box;
  }
  h1 { margin: 0 0 8px; font-weight: 600; letter-spacing: 0.5px; font-size: 22px; }
  p.sub { margin: 0 0 18px; color: #8a97ad; font-size: 13px; }
  .stage {
    position: relative;
    border-radius: 14px;
    overflow: hidden;
    box-shadow: 0 22px 60px rgba(0,0,0,0.55), inset 0 0 0 1px rgba(255,255,255,0.07);
    background: #070a12;
  }
  #sim {
    display: block;
    width: 480px;
    height: 480px;
    cursor: crosshair;
    background: linear-gradient(180deg, #0c1322 0%, #060810 100%);
  }
  .controls {
    margin-top: 18px;
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    appearance: none;
    border: 1px solid rgba(255,255,255,0.14);
    background: linear-gradient(180deg, #1c2740, #131a2b);
    color: #e8eef7;
    padding: 10px 18px;
    font-size: 14px;
    font-weight: 500;
    border-radius: 9px;
    cursor: pointer;
    transition: transform 0.08s ease, background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
    min-width: 96px;
  }
  button:hover { background: linear-gradient(180deg, #243357, #182036); border-color: rgba(255,255,255,0.24); }
  button:active { transform: translateY(1px) scale(0.99); }
  button.paused { border-color: #f0a93b; color: #ffd089; }
  .hint { margin-top: 12px; color: #6b7689; font-size: 12px; text-align: center; max-width: 480px; }
</style>
</head>
<body>
  <h1>Bouncing Ball Playground</h1>
  <p class="sub">Click the canvas to drop a ball. Gravity and edges do the rest.</p>
  <div class="stage">
    <canvas id="sim" width="480" height="480"></canvas>
  </div>
  <div class="controls">
    <button id="drop">Drop</button>
    <button id="play">Pause</button>
    <button id="clear">Clear</button>
  </div>
  <div class="hint">Tip: clicking the canvas spawns a ball at the cursor. The ball is pulled down by gravity and bounces off the walls with a little energy loss.</div>

<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');

  // Logical canvas size (matches the width/height attributes).
  const W = canvas.width;
  const H = canvas.height;

  // Physics constants (per unit dt where dt=1 is one "standard" step).
  const GRAVITY = 0.45;
  const RESTITUTION = 0.82;
  const AIR_FRICTION = 0.999;
  const FLOOR_FRICTION = 0.98;

  const palette = [
    '#ff5e7a', '#ffae3b', '#4dd2ff', '#7af0a3', '#b07bff', '#ffd166', '#5eead4'
  ];
  let colorIdx = 0;

  const balls = [];

  function rand(a, b) { return a + Math.random() * (b - a); }

  function makeBall(x, y, vx, vy, r) {
    if (r === undefined || r === null || !isFinite(r) || r <= 0) {
      r = rand(14, 26);
    }
    r = Math.max(4, r);
    const color = palette[colorIdx % palette.length];
    colorIdx++;
    return { x, y, vx, vy, r, color, rot: 0 };
  }

  function addBall(x, y, vx, vy, r) {
    if (typeof vx !== 'number' || !isFinite(vx)) vx = 0;
    if (typeof vy !== 'number' || !isFinite(vy)) vy = 0;
    const b = makeBall(x, y, vx, vy, r);
    // Clamp inside the canvas immediately so it can never start out-of-bounds.
    b.x = Math.max(b.r, Math.min(W - b.r, b.x));
    b.y = Math.max(b.r, Math.min(H - b.r, b.y));
    balls.push(b);
    return b;
  }

  function clearBalls() {
    balls.length = 0;
  }

  function step(dt) {
    if (dt === undefined) dt = 1;
    if (!isFinite(dt)) dt = 1;
    if (dt < 0) dt = 0;

    for (const b of balls) {
      // Gravity accelerates downward.
      b.vy += GRAVITY * dt;

      // Mild air friction so things settle eventually.
      const fric = Math.pow(AIR_FRICTION, dt);
      b.vx *= fric;
      b.vy *= fric;

      // Integrate position.
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // Left wall.
      if (b.x - b.r < 0) {
        b.x = b.r;
        if (b.vx < 0) b.vx = -b.vx * RESTITUTION;
      }
      // Right wall.
      else if (b.x + b.r > W) {
        b.x = W - b.r;
        if (b.vx > 0) b.vx = -b.vx * RESTITUTION;
      }

      // Ceiling.
      if (b.y - b.r < 0) {
        b.y = b.r;
        if (b.vy < 0) b.vy = -b.vy * RESTITUTION;
      }
      // Floor.
      else if (b.y + b.r > H) {
        b.y = H - b.r;
        if (b.vy > 0) b.vy = -b.vy * RESTITUTION;
        // Extra damping when in contact with the floor so balls come to rest.
        b.vx *= FLOOR_FRICTION;
      }

      // Visual spin hint tied to horizontal motion.
      b.rot += b.vx * 0.05 * dt;
    }

    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Subtle grid background.
    ctx.save();
    ctx.globalAlpha = 0.06;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    const grid = 40;
    for (let x = grid; x < W; x += grid) {
      ctx.beginPath(); ctx.moveTo(x + 0.5, 0); ctx.lineTo(x + 0.5, H); ctx.stroke();
    }
    for (let y = grid; y < H; y += grid) {
      ctx.beginPath(); ctx.moveTo(0, y + 0.5); ctx.lineTo(W, y + 0.5); ctx.stroke();
    }
    ctx.restore();

    // Balls.
    for (const b of balls) {
      // Soft glow.
      ctx.save();
      ctx.shadowColor = b.color;
      ctx.shadowBlur = 18;
      ctx.fillStyle = b.color;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // Highlight.
      ctx.save();
      ctx.globalAlpha = 0.35;
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.3, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  // ---- Programmatic API (used by grading) ----
  window.sim = {
    w: W,
    h: H,
    balls() {
      // Return plain data copies so external code can't mutate internals.
      return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r }));
    },
    addBall,
    clear: clearBalls,
    step
  };

  // ---- UI wiring ----
  const playBtn = document.getElementById('play');
  let playing = true;
  let rafId = null;
  let lastT = null;

  function setPlaying(p) {
    playing = p;
    if (playing) {
      playBtn.textContent = 'Pause';
      playBtn.classList.remove('paused');
      lastT = null;
      loop();
    } else {
      playBtn.textContent = 'Play';
      playBtn.classList.add('paused');
      if (rafId) cancelAnimationFrame(rafId);
      rafId = null;
    }
  }

  function loop(t) {
    if (!playing) return;
    if (lastT === null) lastT = t || performance.now();
    const now = t || performance.now();
    let dt = (now - lastT) / 16.6667; // normalize to ~1 per 60fps frame
    lastT = now;
    if (dt > 3) dt = 3; // clamp big frame gaps
    if (dt <= 0) dt = 0.0001;
    step(dt);
    rafId = requestAnimationFrame(loop);
  }

  playBtn.addEventListener('click', () => setPlaying(!playing));

  document.getElementById('drop').addEventListener('click', () => {
    addBall(rand(W * 0.3, W * 0.7), rand(40, 120), rand(-2, 2), 0);
    draw();
  });

  document.getElementById('clear').addEventListener('click', () => {
    clearBalls();
    draw();
  });

  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (W / rect.width);
    const y = (e.clientY - rect.top) * (H / rect.height);
    addBall(x, y, 0, 0);
    draw();
  });

  // Seed a ball so the playground looks alive on load.
  addBall(W * 0.5, 80, 2, 0);
  draw();
  setPlaying(true);
})();
</script>
</body>
</html>
